<script>
document.addEventListener('DOMContentLoaded',()=>{const form=document.getElementById('returnRefundForm');if(!form)return;const panels=[...form.querySelectorAll('[data-step]')],indicators=[...document.querySelectorAll('[data-step-indicator]')],issues=@json($issues),money=n=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(n),showStep=n=>{panels.forEach(p=>p.classList.toggle('is-active',Number(p.dataset.step)===n));indicators.forEach(i=>i.classList.toggle('is-active',Number(i.dataset.stepIndicator)<=n));window.scrollTo({top:0,behavior:'smooth'});};let step=1;const selectedIssue=()=>form.querySelector('input[name="issue_category"]:checked'),selectedReason=()=>form.querySelector('input[name="issue_reason"]:checked');form.querySelectorAll('[data-issue]').forEach(input=>input.addEventListener('change',()=>{document.querySelectorAll('[data-reasons]').forEach(group=>group.hidden=group.dataset.reasons!==input.value);document.querySelectorAll('[data-reasons] input').forEach(r=>{r.checked=false});}));form.querySelectorAll('[data-next]').forEach(btn=>btn.addEventListener('click',()=>{if(step===1&&!selectedIssue()){alert('Choose an issue first.');return}if(step===2&&!selectedReason()){alert('Choose a reason first.');return}if(step===3&&!form.querySelector('[data-item-checkbox]:checked')){alert('Select at least one affected item.');return}if(step<4){step++;if(step===4){const issue=selectedIssue(),reason=selectedReason();document.getElementById('reviewIssue').textContent=issues[issue.value].label;document.getElementById('reviewReason').textContent=reason.value;document.getElementById('reviewSolution').textContent=issues[issue.value].solution;document.getElementById('reviewAmount').textContent=document.getElementById('refundTotal').textContent;document.getElementById('reviewItems').textContent=[...form.querySelectorAll('[data-item-checkbox]:checked')].map(c=>c.closest('.rr-item').querySelector('strong').textContent).join(', ')}showStep(step)}}));form.querySelectorAll('[data-back]').forEach(btn=>btn.addEventListener('click',()=>{if(step>1){step--;showStep(step)}}));form.querySelectorAll('[data-item-checkbox]').forEach(check=>check.addEventListener('change',()=>{const q=form.querySelector(`[data-for-item="${check.dataset.itemId}"]`);q.disabled=!check.checked;updateTotal()}));form.querySelectorAll('[data-quantity]').forEach(q=>q.addEventListener('input',updateTotal));function updateTotal(){let total=0;form.querySelectorAll('[data-item-checkbox]:checked').forEach(c=>{const q=form.querySelector(`[data-for-item="${c.dataset.itemId}"]`);total+=Number(c.dataset.unitRefund)*Number(q.value||0)});document.getElementById('refundTotal').textContent=money(total)}const description=document.getElementById('description');description.addEventListener('input',()=>document.getElementById('descriptionCount').textContent=`${description.value.length} / 2000`);const images=document.getElementById('images'),preview=document.getElementById('imagePreview');images.addEventListener('change',()=>{preview.innerHTML='';[...images.files].slice(0,6).forEach(file=>{const img=document.createElement('img');img.alt=file.name;img.src=URL.createObjectURL(file);preview.appendChild(img)})});document.getElementById('video').addEventListener('change',e=>{document.getElementById('videoName').textContent=e.target.files[0]?.name||'MP4, MOV, or WEBM. Maximum 200 MB.'});const existingIssue=form.querySelector('input[name="issue_category"]:checked');if(existingIssue){existingIssue.dispatchEvent(new Event('change'));}updateTotal();});
</script>
<script>
document.addEventListener('DOMContentLoaded',()=>{const form=document.getElementById('returnRefundForm');if(!form)return;const imageInput=document.getElementById('images'),preview=document.getElementById('imagePreview'),imageFiles=[];const syncImages=()=>{const transfer=new DataTransfer();imageFiles.forEach(file=>transfer.items.add(file));imageInput.files=transfer.files;preview.innerHTML='';imageFiles.forEach((file,index)=>{const wrap=document.createElement('span');wrap.className='relative inline-block';const img=document.createElement('img');img.src=URL.createObjectURL(file);img.alt=file.name;const remove=document.createElement('button');remove.type='button';remove.textContent='×';remove.setAttribute('aria-label','Remove '+file.name);remove.className='absolute -right-1 -top-2 grid h-5 w-5 place-items-center rounded-full bg-stone-900 text-xs text-white';remove.addEventListener('click',()=>{imageFiles.splice(index,1);syncImages()});wrap.append(img,remove);preview.appendChild(wrap)})};imageInput.addEventListener('change',()=>{imageFiles.splice(0,imageFiles.length,...[...imageInput.files].slice(0,6));syncImages()});const amount=()=>{let total=0;form.querySelectorAll('[data-item-checkbox]:checked').forEach(c=>{const q=form.querySelector(`[data-for-item="${c.dataset.itemId}"]`);total+=Number(c.dataset.unitRefund)*Number(q.value||0)});return total};const refreshAmount=()=>{const formatted=new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(amount());['refundPrice','refundTotal','reviewPrice','reviewAmount'].forEach(id=>{const el=document.getElementById(id);if(el)el.textContent=formatted})};form.querySelectorAll('[data-item-checkbox],[data-quantity]').forEach(el=>el.addEventListener('change',refreshAmount));form.querySelectorAll('[data-next]').forEach(btn=>btn.addEventListener('click',()=>setTimeout(()=>{if(!document.querySelector('[data-step="4"].is-active'))return;const issue=form.querySelector('input[name="issue_category"]:checked'),reason=form.querySelector('input[name="issue_reason"]:checked'),method=form.querySelector('[name="refund_method"]:checked,select[name="refund_method"] option:checked'),email=document.getElementById('buyer_email');document.getElementById('reviewMethod').textContent=method?.textContent||method?.value||'Will be confirmed by support';document.getElementById('reviewEmail').textContent=email.value;document.getElementById('reviewDescription').textContent=document.getElementById('description').value;document.getElementById('reviewEvidence').textContent=[...imageFiles].map(file=>file.name).concat(document.getElementById('video').files[0]?.name||[]).join(', ')||'No files attached';refreshAmount()},0));refreshAmount()});
</script>
